# =============================================================================
# Chapter 3 figures: Hypothesis Testing and Effect Sizes
#
# Run from the project root:
#   Rscript r_code/figures/chapter_03.R
#
# Figure 3.1 simulates the sampling distribution of the mean CESDDiff for the
# diet group. Figure 3.2 shows power curves for an independent sample t-test.
# Captions and alt text live here, next to the code.
# figures/chapter_03/figures.yml is generated by save_book_fig(); do not edit
# it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(ggplot2)
  library(readr)
  library(scales)
})

assert_book_font()

# ---- Data -------------------------------------------------------------------

depression <- read_csv(
  "data/depression_diet_treatment.csv", show_col_types = FALSE
)

diet_diff <- depression$CESDDiff[depression$Group == "Diet"]

# ---- Figure 3.1: sampling distribution of the mean CESDDiff -----------------

# The simulation resamples the 37 observed diet-group change scores, drawing
# groups of 75. This is the repetition described in Section 3.3.
set.seed(2026)
n_sim <- 10000
n_boot <- 75
bin_width <- 0.4

sample_means <- replicate(
  n_sim, mean(sample(diet_diff, n_boot, replace = TRUE))
)
boot_mean <- mean(sample_means)
boot_sd <- sd(sample_means)

breaks <- seq(
  floor(min(sample_means) / bin_width) * bin_width,
  ceiling(max(sample_means) / bin_width) * bin_width,
  by = bin_width
)
hist_counts <- hist(sample_means, breaks = breaks, plot = FALSE)$counts
curve_peak <- n_sim * bin_width * dnorm(boot_mean, boot_mean, boot_sd)
y_top <- max(c(hist_counts, curve_peak)) * 1.08

p31 <- ggplot(
  data.frame(mean_diff = sample_means), aes(x = mean_diff)
) +
  geom_histogram(
    aes(y = after_stat(count)), binwidth = bin_width, boundary = 0,
    fill = book_palette[["sky_blue"]], colour = BOOK_INK, linewidth = 0.3
  ) +
  stat_function(
    fun = function(x) dnorm(x, boot_mean, boot_sd) * n_sim * bin_width,
    colour = book_palette[["vermillion"]], linewidth = 1
  ) +
  geom_vline(
    xintercept = boot_mean, linetype = "dashed", colour = BOOK_INK,
    linewidth = 0.5
  ) +
  annotate(
    "text", x = boot_mean, y = y_top,
    label = sprintf("Mean = %.2f", boot_mean),
    hjust = -0.05, vjust = 1.2, size = 3.2, colour = BOOK_INK
  ) +
  scale_x_continuous(
    breaks = seq(-10, -2, 2), expand = expansion(mult = c(0.02, 0.02))
  ) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.12))) +
  labs(
    x = "Mean change in CESD score (points)",
    y = "Number of simulated samples"
  ) +
  book_theme()

save_book_fig(
  p31,
  chapter = 3, id = "3.1", type = "hist", slug = "sampling_distribution_cesddiff",
  caption = paste(
    "Simulated sampling distribution of the mean CESDDiff for 10,000 samples",
    "of 75 students drawn from the observed diet-group change scores. The",
    "histogram forms a symmetric bell shape centered near -6.03 points, with",
    "a normal curve overlaid."
  ),
  alt = paste(
    "Histogram of 10,000 simulated sample means of CESDDiff, each from 75",
    "students drawn from the diet group. The bars form a symmetric bell shape",
    "centered near -6 points, with almost all sample means between about -8.4",
    "and -3.8."
  ),
  direct_labels = TRUE,
  author_note = paste(
    "The simulation resamples the 37 observed diet-group CESDDiff values",
    "10,000 times with samples of 75. It illustrates the Central Limit Theorem",
    "and is not a population estimate."
  )
)

# ---- Figure 3.2: power curves ----------------------------------------------

# Two-sided independent sample t-test, alpha = .05, equal group sizes. The
# x-axis is the total sample size across both groups.
effect_sizes <- c(
  "Small (d = 0.2)" = 0.2,
  "Medium (d = 0.5)" = 0.5,
  "Large (d = 0.8)" = 0.8
)
n_values <- seq(4, 800, by = 2)

power_df <- do.call(rbind, lapply(names(effect_sizes), function(nm) {
  d_eff <- effect_sizes[[nm]]
  data.frame(
    effect = factor(nm, levels = names(effect_sizes)),
    N = n_values,
    power = vapply(n_values, function(N) {
      power.t.test(
        n = N / 2, delta = d_eff, sd = 1, sig.level = .05,
        type = "two.sample", alternative = "two.sided"
      )$power
    }, numeric(1))
  )
}))

p32 <- ggplot(
  power_df, aes(x = N, y = power, colour = effect, linetype = effect)
) +
  geom_hline(
    yintercept = 0.8, linetype = "dashed", colour = BOOK_MUTED,
    linewidth = 0.4
  ) +
  geom_line(linewidth = 0.9) +
  annotate(
    "text", x = 420, y = 0.82, label = "80% power",
    hjust = 0, size = 3.0, colour = BOOK_INK
  ) +
  scale_colour_manual(
    values = c(
      "Small (d = 0.2)" = book_palette[["bluish_green"]],
      "Medium (d = 0.5)" = book_palette[["blue"]],
      "Large (d = 0.8)" = book_palette[["vermillion"]]
    ),
    name = "Effect size"
  ) +
  scale_linetype_manual(
    values = c(
      "Small (d = 0.2)" = "dotted",
      "Medium (d = 0.5)" = "dashed",
      "Large (d = 0.8)" = "solid"
    ),
    name = "Effect size"
  ) +
  scale_x_continuous(
    breaks = seq(0, 800, 200), expand = expansion(mult = c(0.01, 0.02))
  ) +
  scale_y_continuous(
    labels = percent_format(accuracy = 1), limits = c(0, 1),
    breaks = seq(0, 1, 0.2)
  ) +
  labs(x = "Total sample size", y = "Statistical power") +
  book_theme()

save_book_fig(
  p32,
  chapter = 3, id = "3.2", type = "line", slug = "power_curves",
  caption = paste(
    "Power curves for a two-sided independent sample t-test at alpha = .05,",
    "with equal group sizes. Each line shows how power rises with the total",
    "sample size for a small, medium, or large effect. The dashed horizontal",
    "line marks the conventional 80% target."
  ),
  alt = paste(
    "Line chart of statistical power against total sample size for three",
    "effect sizes. The large-effect line reaches 80% power near 52",
    "participants, the medium-effect line near 128, and the small-effect line",
    "near 788. A dashed horizontal line marks 80% power."
  ),
  direct_labels = TRUE
)
